    "excerpt": "/**
   * The step's own bash does nothing else either. A `gh pr create` or a
   * `gh workflow run` beside the notice would be the automatic-update capability
   * this workflow was deliberately not given.
   */
  test("its shell opens no pull request and starts no run", () => {
    const bodies = steps.map((step) => step.run ?? "").join("\n");
    expect(bodies).not.toMatch(/gh\s+pr\s+create/);
    expect(bodies).not.toMatch(/gh\s+workflow\s+run/);
  });"
  },
  {
    "path": "docs/work/how-it-works/what-starts-a-run.md",
    "lines": "81-85",
    "excerpt": "`atomaton-new-release.yml` is the one that listens for nothing at all. It compares
`.github/atomaton-release.json` against the latest release, nightly, and opens (or
updates) a single issue when they differ — the only way a repository that has been
quiet for a while learns that a newer release exists. What it does with the answer
is [move to a newer release](../../runtime/tasks/move-to-a-newer-release.md)."
  },
  {
    "path": "src/entrypoints/machinery/notify_new_release.test.ts",
    "lines": "402-413",
    "excerpt": "/** The file both sides changed is the whole reason an update stops at a pull request. */
  test("a both-sides change is named in the verdict, as the decision to make", () => {
    const dir = checkout({ ...BASE_FILES, [CHECK]: "check: customised by the adopter\n" }, "v0.1.0");
    const r = runWithFakeGh(scriptPath("notify_new_release.ts"), ["--repo", "owner/repo"], {
      cwd: dir,
      rules: [...reads("v0.2.0"), search(0), { match: ["issue", "create"] }],
    });
    expect(r.status).toBe(0);
    const body = writeBody(r.ghCalls.find((call) => call[1] === "create") ?? []);
    expect(body).toContain("needs a decision");
    expect(body).toContain(`\`${CHECK}\``);
  });"
  }
